import{_ as o,o as a,c as r,ag as d}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"认知路径","description":"","frontmatter":{},"headers":[],"relativePath":"30-学习路径/path-认知路径.md","filePath":"30-学习路径/path-认知路径.md","lastUpdated":1778031108000}'),n={name:"30-学习路径/path-认知路径.md"};function s(e,t,l,p,h,u){return a(),r("div",null,[...t[0]||(t[0]=[d(`<h1 id="认知路径" tabindex="-1">认知路径 <a class="header-anchor" href="#认知路径" aria-label="Permalink to &quot;认知路径&quot;">​</a></h1><blockquote><p>系统学习路径：按次第建立对七大核心心智模型的完整理解。 适合希望系统建立智慧体系的学习者。</p></blockquote><hr><h2 id="路径总览" tabindex="-1">路径总览 <a class="header-anchor" href="#路径总览" aria-label="Permalink to &quot;路径总览&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>对境不住（心法基础）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>对法不执（心法深化）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>自然务实（方法论）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>圆融中和（处世智慧）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>历境炼心（实践功夫）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>天人合一（世界观）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>性命双修（圆满整合）</span></span></code></pre></div><hr><h2 id="第一阶段-对境不住-不被现象迷惑" tabindex="-1">第一阶段：对境不住 | 不被现象迷惑 <a class="header-anchor" href="#第一阶段-对境不住-不被现象迷惑" aria-label="Permalink to &quot;第一阶段：对境不住 | 不被现象迷惑&quot;">​</a></h2><p><strong>核心问题</strong>：为什么我总是被外界带着跑？</p><p><strong>目标</strong>：学会觉察——知道自己在做什么、想什么，不被现象牵着走。</p><p><strong>学习方法</strong>：</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>参考资料</th></tr></thead><tbody><tr><td>1.1</td><td>理解什么是&quot;相&quot;——一切外在现象都是相</td><td><a href="/10-核心模型/model-对境不住">对境不住模型</a></td></tr><tr><td>1.2</td><td>学习区分&quot;事实&quot;和&quot;我的反应&quot;</td><td>原子：离相即客观、知见无见</td></tr><tr><td>1.3</td><td>实践&quot;保持平静的窍诀&quot;</td><td>原子：保持平静的窍诀</td></tr><tr><td>1.4</td><td>理解&quot;过去心不可得&quot;的三层含义</td><td>原子：三心不可得</td></tr></tbody></table><p><strong>实战应用</strong>：</p><ul><li><a href="/20-专题研究/topic-情绪">如何处理情绪</a> — 觉察情绪的第一步</li><li><a href="/20-专题研究/topic-焦虑">如何面对焦虑</a> — 焦虑是对未来&quot;相&quot;的执着</li></ul><p><strong>检验标准</strong>：当你被批评时，第一反应不是反驳，而是先听完。</p><blockquote><p><strong>关键金句</strong>：&quot;不平静时问自己：&#39;我为什么要不平静？这样正确吗？&#39;&quot;</p></blockquote><hr><h2 id="第二阶段-对法不执-放下一切执着" tabindex="-1">第二阶段：对法不执 | 放下一切执着 <a class="header-anchor" href="#第二阶段-对法不执-放下一切执着" aria-label="Permalink to &quot;第二阶段：对法不执 | 放下一切执着&quot;">​</a></h2><p><strong>核心问题</strong>：我知道不该被现象带跑，但为什么还是放不下？</p><p><strong>目标</strong>：从&quot;不被外部带跑&quot;深化到&quot;不执着于任何东西，包括方法本身&quot;。</p><p><strong>学习方法</strong>：</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>参考资料</th></tr></thead><tbody><tr><td>2.1</td><td>理解&quot;法尚应舍&quot;——连方法都要放下</td><td><a href="/10-核心模型/model-对法不执">对法不执模型</a></td></tr><tr><td>2.2</td><td>学习不执功德相——做好事不留念</td><td>原子：不执功德相</td></tr><tr><td>2.3</td><td>理解&quot;即得不等于得后&quot;——当下即是</td><td>原子：即得不等于得后</td></tr><tr><td>2.4</td><td>通达无我法——一切自然流露</td><td>原子：通达无我法</td></tr></tbody></table><p><strong>实战应用</strong>：</p><ul><li><a href="/20-专题研究/topic-财富与布施">如何看待财富与布施</a> — 放下对功德的执着</li><li><a href="/20-专题研究/topic-忍辱与原谅">如何面对忍辱与原谅</a> — 放下&quot;被侮辱&quot;的标签</li></ul><p><strong>检验标准</strong>：你做了一件好事之后，心里有没有&quot;我做了好事&quot;的感觉？</p><blockquote><p><strong>关键金句</strong>：&quot;雷锋帮完人就走了，不等着对方说谢谢。&quot;</p></blockquote><hr><h2 id="第三阶段-自然务实-抓核心-做实事" tabindex="-1">第三阶段：自然务实 | 抓核心，做实事 <a class="header-anchor" href="#第三阶段-自然务实-抓核心-做实事" aria-label="Permalink to &quot;第三阶段：自然务实 | 抓核心，做实事&quot;">​</a></h2><p><strong>核心问题</strong>：道理懂了，但是怎么落实到行动上？</p><p><strong>目标</strong>：把道理变成行动——不绕弯子，抓核心，做该做的事。</p><p><strong>学习方法</strong>：</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>参考资料</th></tr></thead><tbody><tr><td>3.1</td><td>理解&quot;无为&quot;——不是不做，是不乱做</td><td><a href="/10-核心模型/model-自然务实">自然务实模型</a></td></tr><tr><td>3.2</td><td>学习&quot;因上精进，果上随缘&quot;</td><td>原子：因上精进果上随缘</td></tr><tr><td>3.3</td><td>理解&quot;经验不能照搬&quot;</td><td>原子：经验不能照搬</td></tr><tr><td>3.4</td><td>实践&quot;信解行证&quot;的四步法</td><td>原子：信解行证</td></tr></tbody></table><p><strong>实战应用</strong>：</p><ul><li><a href="/20-专题研究/topic-选择">如何做出选择</a> — 务实决策</li><li><a href="/20-专题研究/topic-工作修行">在工作中修行</a> — 工作即修行</li></ul><p><strong>检验标准</strong>：遇到问题时，你更多是在想&quot;怎么办&quot;还是&quot;为什么又是我&quot;？</p><blockquote><p><strong>关键金句</strong>：&quot;做就是了。行动胜过千言万语。&quot;</p></blockquote><hr><h2 id="第四阶段-圆融中和-不走极端" tabindex="-1">第四阶段：圆融中和 | 不走极端 <a class="header-anchor" href="#第四阶段-圆融中和-不走极端" aria-label="Permalink to &quot;第四阶段：圆融中和 | 不走极端&quot;">​</a></h2><p><strong>核心问题</strong>：我努力了，但总是走极端——要么太紧，要么太松。</p><p><strong>目标</strong>：找到中道——在每一件事情上做到恰到好处。</p><p><strong>学习方法</strong>：</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>参考资料</th></tr></thead><tbody><tr><td>4.1</td><td>理解&quot;守中&quot;——不走极端的智慧</td><td><a href="/10-核心模型/model-圆融中和">圆融中和模型</a></td></tr><tr><td>4.2</td><td>学习整体观——看待问题的全局视角</td><td>原子：整体观定善恶</td></tr><tr><td>4.3</td><td>理解&quot;智慧布施&quot;——不给、不贪、不吝</td><td>原子：智慧布施</td></tr><tr><td>4.4</td><td>实践&quot;无断无灭&quot;——不落两边</td><td>原子：无断无灭</td></tr></tbody></table><p><strong>实战应用</strong>：</p><ul><li><a href="/20-专题研究/topic-人际关系">如何处理人际关系</a> — 待人处事的中道</li><li><a href="/20-专题研究/topic-亲子教育">如何教育子女</a> — 不偏不倚的教育</li></ul><p><strong>检验标准</strong>：在争论中，你能不能同时看到对方立场中的合理之处？</p><blockquote><p><strong>关键金句</strong>：&quot;守中不是停在中间不动，是不走极端。就像开车，要不断微调方向。&quot;</p></blockquote><hr><h2 id="第五阶段-历境炼心-在事上磨" tabindex="-1">第五阶段：历境炼心 | 在事上磨 <a class="header-anchor" href="#第五阶段-历境炼心-在事上磨" aria-label="Permalink to &quot;第五阶段：历境炼心 | 在事上磨&quot;">​</a></h2><p><strong>核心问题</strong>：我在静坐时很平静，但一遇到事情就乱。</p><p><strong>目标</strong>：在每一个生活场景中磨炼心性——顺境不飘，逆境不垮。</p><p><strong>学习方法</strong>：</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>参考资料</th></tr></thead><tbody><tr><td>5.1</td><td>理解&quot;烦恼即菩提&quot;</td><td><a href="/10-核心模型/model-历境炼心">历境炼心模型</a></td></tr><tr><td>5.2</td><td>学习&quot;顺逆皆修&quot;</td><td>原子：顺逆皆修</td></tr><tr><td>5.3</td><td>理解&quot;冤亲平等&quot;</td><td>原子：冤亲平等</td></tr><tr><td>5.4</td><td>实践&quot;放下屠刀&quot;——随时回归清净</td><td>原子：放下屠刀立地成佛</td></tr></tbody></table><p><strong>实战应用</strong>：</p><ul><li><a href="/20-专题研究/topic-工作修行">在工作中修行</a> — 工作中的历境炼心</li><li><a href="/20-专题研究/topic-疾病与健康">如何面对疾病与健康</a> — 病中的炼心</li><li><a href="/20-专题研究/topic-忍辱与原谅">如何面对忍辱与原谅</a> — 被伤害时的炼心</li></ul><p><strong>检验标准</strong>：遇到让你生气的事情，你多久能平静下来？</p><blockquote><p><strong>关键金句</strong>：&quot;一切烦恼为如来种——烦恼是觉悟的机会，不是敌人。&quot;</p></blockquote><hr><h2 id="第六阶段-天人合一-建立宇宙观" tabindex="-1">第六阶段：天人合一 | 建立宇宙观 <a class="header-anchor" href="#第六阶段-天人合一-建立宇宙观" aria-label="Permalink to &quot;第六阶段：天人合一 | 建立宇宙观&quot;">​</a></h2><p><strong>核心问题</strong>：修行的终极目标是什么？</p><p><strong>目标</strong>：理解&quot;我与宇宙是一体&quot;的世界观，建立修行的终极坐标系。</p><p><strong>学习方法</strong>：</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>参考资料</th></tr></thead><tbody><tr><td>6.1</td><td>理解&quot;缘起性空&quot;——一切不永恒</td><td><a href="/10-核心模型/model-天人合一">天人合一模型</a></td></tr><tr><td>6.2</td><td>学习&quot;万法一体&quot;——你中有我，我中有你</td><td>原子：万法一体</td></tr><tr><td>6.3</td><td>理解&quot;因果不空&quot;</td><td>原子：因果不空</td></tr><tr><td>6.4</td><td>实践&quot;观天之道&quot;——在生活中观察规律</td><td>原子：观天之道执天之行</td></tr></tbody></table><p><strong>实战应用</strong>：</p><ul><li><a href="/20-专题研究/topic-生死观">如何面对生死</a> — 天人合一的终极应用</li></ul><p><strong>检验标准</strong>：你是否能从&quot;我&quot;的局限中跳出来，看到更大的图景？</p><blockquote><p><strong>关键金句</strong>：&quot;一滴水与大海融为一体——到底是大海得到一滴水，还是一滴水得到了大海？&quot;</p></blockquote><hr><h2 id="第七阶段-性命双修-身心圆满" tabindex="-1">第七阶段：性命双修 | 身心圆满 <a class="header-anchor" href="#第七阶段-性命双修-身心圆满" aria-label="Permalink to &quot;第七阶段：性命双修 | 身心圆满&quot;">​</a></h2><p><strong>核心问题</strong>：如何将一切理论和实践整合到生命中？</p><p><strong>目标</strong>：性命双修——既要明心，也要修身，达到形神俱妙。</p><p><strong>学习方法</strong>：</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>参考资料</th></tr></thead><tbody><tr><td>7.1</td><td>学习&quot;似守非守&quot;的火候</td><td><a href="/10-核心模型/model-性命双修">性命双修模型</a></td></tr><tr><td>7.2</td><td>掌握静坐方法</td><td>原子：神守黄房、绵绵若存</td></tr><tr><td>7.3</td><td>理解&quot;百日功灵&quot;</td><td>原子：百日功灵</td></tr><tr><td>7.4</td><td>悟后起修——永无止境</td><td>原子：形神俱妙</td></tr></tbody></table><p><strong>实战应用</strong>：</p><ul><li><a href="/20-专题研究/topic-入门实修">如何开始实修</a> — 实修的起点</li><li><a href="/20-专题研究/topic-修行进阶">修行进阶</a> — 从入门到深入</li></ul><p><strong>检验标准</strong>：你是否能在一件日常小事中，同时感受到身体的放松和心的清净？</p><blockquote><p><strong>关键金句</strong>：&quot;不可用心守，不可无意求。守得太紧就着相，守得太松就无效。&quot;</p></blockquote><hr><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><h3 id="速度建议" tabindex="-1">速度建议 <a class="header-anchor" href="#速度建议" aria-label="Permalink to &quot;速度建议&quot;">​</a></h3><ul><li><strong>第一阶段</strong>：1-2周，打好觉察基础</li><li><strong>第二阶段</strong>：2-3周，反复体会&quot;放下&quot;</li><li><strong>第三阶段</strong>：1-2周，重点在行动</li><li><strong>第四阶段</strong>：2-3周，在生活中找&quot;度&quot;</li><li><strong>第五阶段</strong>：长期，每一个烦恼都是一次考试</li><li><strong>第六阶段</strong>：1-2周，反复体悟宇宙观</li><li><strong>第七阶段</strong>：长期，一日修行一日功</li></ul><blockquote><p>不必按部就班地&quot;学完&quot;——遇到哪些问题，就去对应的阶段找答案。</p></blockquote><h3 id="最佳配套阅读" tabindex="-1">最佳配套阅读 <a class="header-anchor" href="#最佳配套阅读" aria-label="Permalink to &quot;最佳配套阅读&quot;">​</a></h3><ul><li><a href="/核心摘要">核心摘要</a> — 全体系精华浓缩</li><li><a href="/学习指南">学习指南</a> — 按学习阶段组织的指南</li></ul><hr><blockquote><p>创建日期：2026-05-06</p></blockquote>`,84)])])}const g=o(n,[["render",s]]);export{q as __pageData,g as default};
